/**
 * The typed tables of the flow model, generated by IFC Data from the model. Do not edit: change the model and run `bun tools/typed.ts --write`.
 *
 * How data moves through a pipeline, and the proof that nothing was lost on the way
 *
 * @module
 */
import { defineTable, type Timestamp } from "@intellectual-frontiers/data/sql/typed";

/** Who produces a reason code */
export interface ProducerRow {
  /** The code other tables point to: a short word that does not change */
  readonly code: string;
  /** What a person is shown for the code */
  readonly label: string;
  /** What the code means, where the label is not enough */
  readonly description: string | null;
}

/** What an insert into producer takes: what the database fills may be left out. */
export interface ProducerInsert {
  readonly code: string;
  readonly label: string;
  readonly description?: string | null;
}

/** The key of a row of producer. */
export type ProducerKey = { readonly code: string };

/** Who produces a reason code */
export const producer = defineTable<ProducerRow, ProducerInsert, "producer">({
  alias: "producer",
  name: "producer",
  columns: {
    code: "code",
    label: "label",
    description: "description",
  },
  primaryKey: ["code"],
});

/** A reason code that says why a stage stopped, rejected or lost something, so that no loss is unexplained */
export interface ReasonRow {
  /** What identifies the reason: its code */
  readonly reasonId: string;
  /** What it means, in a sentence */
  readonly meaning: string;
  /** Who produces it */
  readonly producerCode: string;
  /** The stage it is of, where it is of one */
  readonly stage: "received" | "captured" | "parsed" | "mapped" | "validated" | "forwarded" | "dest_verdict" | "usable" | null;
}

/** What an insert into reason takes: what the database fills may be left out. */
export interface ReasonInsert {
  readonly reasonId: string;
  readonly meaning: string;
  readonly producerCode: string;
  readonly stage?: "received" | "captured" | "parsed" | "mapped" | "validated" | "forwarded" | "dest_verdict" | "usable" | null;
}

/** The key of a row of reason. */
export type ReasonKey = { readonly reasonId: string };

/** A reason code that says why a stage stopped, rejected or lost something, so that no loss is unexplained */
export const reason = defineTable<ReasonRow, ReasonInsert, "reason">({
  alias: "reason",
  name: "reason",
  columns: {
    reasonId: "reason_id",
    meaning: "meaning",
    producerCode: "producer_code",
    stage: "stage",
  },
  primaryKey: ["reasonId"],
  foreignKeys: [
    { columns: ["producerCode"], references: "producer", referencesColumns: ["code"] },
  ],
});

/** One load: an id given at the first stage and carried on every row and effect it makes, so that it can be traced and undone as one */
export interface LoadRow {
  /** What identifies the load */
  readonly loadId: string;
  /** What kind of load it is */
  readonly loadType: "delivery" | "backfill" | "incremental" | "replay";
  /** The tenant it is for */
  readonly tenant: string | null;
  /** The sender or system it came from */
  readonly source: string;
  /** When it began */
  readonly startedAt: Timestamp;
  /** When it was undone, where it was */
  readonly rolledBackAt: Timestamp | null;
}

/** What an insert into load takes: what the database fills may be left out. */
export interface LoadInsert {
  readonly loadId: string;
  readonly loadType: "delivery" | "backfill" | "incremental" | "replay";
  readonly tenant?: string | null;
  readonly source: string;
  readonly startedAt: Timestamp;
  readonly rolledBackAt?: Timestamp | null;
}

/** The key of a row of load. */
export type LoadKey = { readonly loadId: string };

/** One load: an id given at the first stage and carried on every row and effect it makes, so that it can be traced and undone as one */
export const load = defineTable<LoadRow, LoadInsert, "load">({
  alias: "load",
  name: "load",
  columns: {
    loadId: "load_id",
    loadType: "load_type",
    tenant: "tenant",
    source: "source",
    startedAt: "started_at",
    rolledBackAt: "rolled_back_at",
  },
  primaryKey: ["loadId"],
});

/** What a stage guarantees to the stage after it, the outcome codes it may give and how its failure is detected: the stage-contract table of a pipeline */
export interface StageContractRow {
  /** What identifies the contract: its pipeline and stage */
  readonly stageContractId: string;
  /** The pipeline it is of */
  readonly pipeline: string;
  /** The stage */
  readonly stage: "received" | "captured" | "parsed" | "mapped" | "validated" | "forwarded" | "dest_verdict" | "usable";
  /** What it may assume of what it is given */
  readonly inputGuarantee: string;
  /** What it guarantees of what it gives */
  readonly outputGuarantee: string;
  /** Who answers for it */
  readonly owner: string;
  /** How a failure of it is found */
  readonly detection: string;
  /** What a ledger row of it stands for */
  readonly grain: "message" | "batch" | "entity";
}

/** What an insert into stage_contract takes: what the database fills may be left out. */
export interface StageContractInsert {
  readonly stageContractId: string;
  readonly pipeline: string;
  readonly stage: "received" | "captured" | "parsed" | "mapped" | "validated" | "forwarded" | "dest_verdict" | "usable";
  readonly inputGuarantee: string;
  readonly outputGuarantee: string;
  readonly owner: string;
  readonly detection: string;
  readonly grain: "message" | "batch" | "entity";
}

/** The key of a row of stage_contract. */
export type StageContractKey = { readonly stageContractId: string };

/** What a stage guarantees to the stage after it, the outcome codes it may give and how its failure is detected: the stage-contract table of a pipeline */
export const stageContract = defineTable<StageContractRow, StageContractInsert, "stageContract">({
  alias: "stageContract",
  name: "stage_contract",
  columns: {
    stageContractId: "stage_contract_id",
    pipeline: "pipeline",
    stage: "stage",
    inputGuarantee: "input_guarantee",
    outputGuarantee: "output_guarantee",
    owner: "owner",
    detection: "detection",
    grain: "grain",
  },
  primaryKey: ["stageContractId"],
});

/** What one stage confirmed of one message, batch or entity, with the load it was in: a row of the stage ledger, only ever added */
export interface LedgerEntryRow {
  /** What identifies the row */
  readonly ledgerEntryId: string;
  /** The message, batch or entity it is about */
  readonly subject: string;
  /** The stage */
  readonly stage: "received" | "captured" | "parsed" | "mapped" | "validated" | "forwarded" | "dest_verdict" | "usable";
  /** What it confirmed */
  readonly outcome: "passed" | "failed" | "rejected" | "accepted" | "unusable";
  /** What the row stands for */
  readonly grain: "message" | "batch" | "entity";
  /** The entities a batch carried at this stage */
  readonly entities: number | null;
  /** When */
  readonly at: Timestamp;
  /** The load it was in */
  readonly loadId: string;
  /** Why, where it did not pass */
  readonly reasonId: string | null;
}

/** What an insert into ledger_entry takes: what the database fills may be left out. */
export interface LedgerEntryInsert {
  readonly ledgerEntryId: string;
  readonly subject: string;
  readonly stage: "received" | "captured" | "parsed" | "mapped" | "validated" | "forwarded" | "dest_verdict" | "usable";
  readonly outcome: "passed" | "failed" | "rejected" | "accepted" | "unusable";
  readonly grain: "message" | "batch" | "entity";
  readonly entities?: number | null;
  readonly at: Timestamp;
  readonly loadId: string;
  readonly reasonId?: string | null;
}

/** The key of a row of ledger_entry. */
export type LedgerEntryKey = { readonly ledgerEntryId: string };

/** What one stage confirmed of one message, batch or entity, with the load it was in: a row of the stage ledger, only ever added */
export const ledgerEntry = defineTable<LedgerEntryRow, LedgerEntryInsert, "ledgerEntry">({
  alias: "ledgerEntry",
  name: "ledger_entry",
  columns: {
    ledgerEntryId: "ledger_entry_id",
    subject: "subject",
    stage: "stage",
    outcome: "outcome",
    grain: "grain",
    entities: "entities",
    at: "at",
    loadId: "load_id",
    reasonId: "reason_id",
  },
  primaryKey: ["ledgerEntryId"],
  foreignKeys: [
    { columns: ["loadId"], references: "load", referencesColumns: ["loadId"] },
    { columns: ["reasonId"], references: "reason", referencesColumns: ["reasonId"] },
  ],
});

/** A message as it first arrived, with the hash of its content and how many times it has been delivered: the intake that makes a redelivery safe */
export interface DeliveryRow {
  /** What identifies the message: its tenant and the id its sender gave it */
  readonly deliveryId: string;
  /** The tenant */
  readonly tenant: string;
  /** The id the sender gave it */
  readonly senderMessageId: string;
  /** The SHA-256 of its content, as first delivered */
  readonly contentSha256: string;
  /** How many times the same content has been delivered */
  readonly deliveryCount: number;
  /** When it was first seen */
  readonly firstSeen: Timestamp;
  /** The load of its first delivery */
  readonly firstLoadLoadId: string;
}

/** What an insert into delivery takes: what the database fills may be left out. */
export interface DeliveryInsert {
  readonly deliveryId: string;
  readonly tenant: string;
  readonly senderMessageId: string;
  readonly contentSha256: string;
  readonly deliveryCount: number;
  readonly firstSeen: Timestamp;
  readonly firstLoadLoadId: string;
}

/** The key of a row of delivery. */
export type DeliveryKey = { readonly deliveryId: string };

/** A message as it first arrived, with the hash of its content and how many times it has been delivered: the intake that makes a redelivery safe */
export const delivery = defineTable<DeliveryRow, DeliveryInsert, "delivery">({
  alias: "delivery",
  name: "delivery",
  columns: {
    deliveryId: "delivery_id",
    tenant: "tenant",
    senderMessageId: "sender_message_id",
    contentSha256: "content_sha_256",
    deliveryCount: "delivery_count",
    firstSeen: "first_seen",
    firstLoadLoadId: "first_load_load_id",
  },
  primaryKey: ["deliveryId"],
  foreignKeys: [
    { columns: ["firstLoadLoadId"], references: "load", referencesColumns: ["loadId"] },
  ],
});

/** A delivery that had the id of one already taken and other content: the original is kept and this is queued to be decided */
export interface DeliveryConflictRow {
  /** What identifies the conflict */
  readonly deliveryConflictId: string;
  /** The SHA-256 of the content that conflicts */
  readonly incomingSha256: string;
  /** Where it is */
  readonly status: "open" | "kept" | "replaced";
  /** When it was seen */
  readonly seenAt: Timestamp;
  /** The message it conflicts with */
  readonly deliveryId: string;
  /** The load that brought it */
  readonly loadId: string;
}

/** What an insert into delivery_conflict takes: what the database fills may be left out. */
export interface DeliveryConflictInsert {
  readonly deliveryConflictId: string;
  readonly incomingSha256: string;
  readonly status: "open" | "kept" | "replaced";
  readonly seenAt: Timestamp;
  readonly deliveryId: string;
  readonly loadId: string;
}

/** The key of a row of delivery_conflict. */
export type DeliveryConflictKey = { readonly deliveryConflictId: string };

/** A delivery that had the id of one already taken and other content: the original is kept and this is queued to be decided */
export const deliveryConflict = defineTable<DeliveryConflictRow, DeliveryConflictInsert, "deliveryConflict">({
  alias: "deliveryConflict",
  name: "delivery_conflict",
  columns: {
    deliveryConflictId: "delivery_conflict_id",
    incomingSha256: "incoming_sha_256",
    status: "status",
    seenAt: "seen_at",
    deliveryId: "delivery_id",
    loadId: "load_id",
  },
  primaryKey: ["deliveryConflictId"],
  foreignKeys: [
    { columns: ["deliveryId"], references: "delivery", referencesColumns: ["deliveryId"] },
    { columns: ["loadId"], references: "load", referencesColumns: ["loadId"] },
  ],
});

/** What a sender says a batch holds: the count to be accounted for, from which every stage and every loss is reconciled */
export interface ManifestRow {
  /** What identifies the batch */
  readonly manifestId: string;
  /** The sender */
  readonly source: string;
  /** The period it covers */
  readonly period: string | null;
  /** How many entities the sender says it sent */
  readonly manifestCount: number;
  /** The load that carried it */
  readonly loadId: string;
}

/** What an insert into manifest takes: what the database fills may be left out. */
export interface ManifestInsert {
  readonly manifestId: string;
  readonly source: string;
  readonly period?: string | null;
  readonly manifestCount: number;
  readonly loadId: string;
}

/** The key of a row of manifest. */
export type ManifestKey = { readonly manifestId: string };

/** What a sender says a batch holds: the count to be accounted for, from which every stage and every loss is reconciled */
export const manifest = defineTable<ManifestRow, ManifestInsert, "manifest">({
  alias: "manifest",
  name: "manifest",
  columns: {
    manifestId: "manifest_id",
    source: "source",
    period: "period",
    manifestCount: "manifest_count",
    loadId: "load_id",
  },
  primaryKey: ["manifestId"],
  foreignKeys: [
    { columns: ["loadId"], references: "load", referencesColumns: ["loadId"] },
  ],
});

